package com.reg21meme.dross.boss.fire.cave;

import com.reg21meme.dross.Dross;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.ResourceLocation;

/**
 * The hermit crab caves, one template each (generated by tools/fire/hermit_caves.py; don't edit by hand): the Cinder
 * Hermit's small dens in the Cinder Wastes, round 2 (the user's look at round 1, November 2, 2026: No. 7's style, dug
 * into hills, and a few shallow underground ones with loot; one crab each).
 * <p>
 * A cave is {@code dross:hermit_cave/<id>}, {@code width} x {@code depth} blocks and {@code layers} tall, the
 * ground block under its way in at layer {@code groundLayer}, its way in at the south: {@code doorX}, {@code doorZ}
 * is the cell you stand in to go in, on that ground (layer {@code groundLayer + 1}; the template's own coordinates).
 * A {@link Kind#HILLSIDE} cave runs back into a hill at about its way in's level, walled in by its own shell of rock
 * (whatever is outside the shell is left as it is: the hill is its roof); {@code roofLayer} is its shell's top layer,
 * so the hill over its {@code rooms} (the den's middle first, then its burrows': standing cells) should reach past
 * {@code roofLayer - groundLayer} blocks over the way in's ground to bury it. An {@link Kind#UNDERGROUND} cave lies on
 * flat land, its floor about 3 blocks down under a low mound, a loot room behind it. {@code probe} is its darkest floor
 * cell (template coordinates), lit so nothing spawns there; {@code lava} how many lava blocks it has (each walled in
 * under and on its four sides). {@code crabs} is its one crab spot: the cell a Cinder Hermit's feet stand in, its
 * middle, with a free box 7 wide, 6 tall and 7 deep round it.
 */
public final class HermitCaveDesigns
{
    private HermitCaveDesigns() {}

    /** Built into a hill, or a shallow den under a mound on flat land. */
    public enum Kind
    {
        HILLSIDE, UNDERGROUND
    }

    public record Cave(String id, String name, Kind kind, String lore, int width, int depth, int layers, int groundLayer,
                       int doorX, int doorZ, int probeX, int probeY, int probeZ, int lava, int roofLayer,
                       List<BlockPos> crabs, List<BlockPos> rooms)
    {
        public ResourceLocation template()
        {
            return new ResourceLocation(Dross.MODID, "hermit_cave/" + id);
        }

        public BlockPos probe()
        {
            return new BlockPos(probeX, probeY, probeZ);
        }

        /** The cell you stand in to go in (template coordinates). */
        public BlockPos door()
        {
            return new BlockPos(doorX, groundLayer + 1, doorZ);
        }

        /** The middle of its den (template coordinates, the cell you stand in). */
        public BlockPos den()
        {
            return rooms.get(0);
        }

        public boolean hillside()
        {
            return kind == Kind.HILLSIDE;
        }

        /** How far its shell's top stands over the ground under its way in (blocks). */
        public int roofRise()
        {
            return roofLayer - groundLayer;
        }
    }

    /** Every cave, in order (their numbers, 1 the Hillside Burrows, 2 the Long Gallery, 3 the Claw Burrows, 4 the Ash Mound Den, 5 the Twin Hump Den). */
    public static final List<Cave> CAVES = List.of(
            new Cave("hillside_burrows", "Hillside Burrows", Kind.HILLSIDE,
                    "No. 7 dug into a hill: a rocky mouth in the hillside, a round den round a Cinder Vent on its mound of basalt and magma, and three burrows off it: the crab's nest at the back, a pool of lava, and a midden of its spare shells.",
                    29, 29, 14, 4, 14, 28, 13, 5, 9, 6, 13,
                    List.of(new BlockPos(14, 5, 6)),
                    List.of(new BlockPos(14, 5, 16), new BlockPos(14, 5, 6), new BlockPos(6, 5, 15), new BlockPos(22, 5, 15))),
            new Cave("long_gallery", "Long Gallery", Kind.HILLSIDE,
                    "A wide mouth in the hillside onto a long gallery dug along the hill, two pillars holding its roof and two Cinder Vents on their mounds; a pool of lava at its west end, a midden of spare shells at its east end, and the crab's nest in a burrow back into the hill.",
                    29, 29, 13, 4, 14, 28, 12, 5, 12, 4, 12,
                    List.of(new BlockPos(14, 5, 7)),
                    List.of(new BlockPos(14, 5, 19), new BlockPos(14, 5, 7), new BlockPos(6, 5, 19), new BlockPos(22, 5, 19))),
            new Cave("claw_burrows", "Claw Burrows", Kind.HILLSIDE,
                    "A narrow mouth in the hillside, a step down into a round den round its Cinder Vent, and three burrows fanned out behind it like a claw's fingers: a pool of lava, the crab's nest deepest in the hill, and a midden of its spare shells.",
                    29, 29, 13, 4, 14, 28, 18, 4, 7, 5, 12,
                    List.of(new BlockPos(14, 4, 6)),
                    List.of(new BlockPos(14, 4, 18), new BlockPos(14, 4, 6), new BlockPos(6, 4, 10), new BlockPos(22, 4, 10))),
            new Cave("ash_mound", "Ash Mound Den", Kind.UNDERGROUND,
                    "A cutting slopes down a block every two into a den 3 blocks under the ground round its Cinder Vent, its roof a low mound of ash with a second vent smoking on top; off it the crab's nest, a pool of lava, and behind a crawl the crab can't follow, a little loot room of decorated pots, suspicious gravel and a barrel.",
                    37, 37, 17, 7, 18, 36, 20, 5, 28, 3, 14,
                    List.of(new BlockPos(10, 5, 20)),
                    List.of(new BlockPos(18, 5, 20), new BlockPos(10, 5, 20), new BlockPos(26, 5, 20), new BlockPos(18, 4, 9))),
            new Cave("twin_hump", "Twin Hump Den", Kind.UNDERGROUND,
                    "Two humps of ash over a shallow den: a cutting slopes down to a vent chamber 3 blocks under the ground, the crab's nest under the bigger hump, a pool of lava to the north, and through a crawl the crab can't follow, a loot room of decorated pots, suspicious gravel and a barrel.",
                    37, 37, 18, 7, 18, 36, 29, 4, 22, 3, 17,
                    List.of(new BlockPos(11, 5, 17)),
                    List.of(new BlockPos(18, 5, 22), new BlockPos(11, 5, 17), new BlockPos(18, 5, 13), new BlockPos(27, 4, 20))));

    /** The numbers (indexes into {@link #CAVES}) of the caves of this kind, in order. */
    public static List<Integer> indexesOf(Kind kind)
    {
        return java.util.stream.IntStream.range(0, CAVES.size()).filter(i -> CAVES.get(i).kind() == kind).boxed().toList();
    }
}
